 14	/**
 15	 * The compiled path's reading of a native binding.  A declaration whose body is
 16	 * exactly builtinPrimitive("pkg.Class.method"), the tight juxtaposition that walk's
 17	 * NativeApp.checkAndLoadNative recognizes, where the string names a public static
 18	 * method of a class of the helpers' package, com.sun.fortress.nativeHelpers., becomes
 19	 * a call of that method through the import java machinery: the component gains
 20	 * import java pkg.{Class.method => alias}, and the body becomes alias(args), the
 21	 * parameters in order, self first for a method of a trait or object (a dotted
 22	 * method's self added, a functional method's moved to the front), as walk's
 23	 * NativeMeth passes them.  A declaration with a varargs parameter is left alone.
 24	 * A string under the helpers' package that names no public static method is a
 25	 * static error at the string.  Any other string is left alone, walk's glue classes
 26	 * ("pkg.Class$Op") among them, so that its body stays a call of builtinPrimitive.
 27	 *
 28	 * Shell.specificRepository turns it on for the compiled path's repository and off
 29	 * for walk's, which loads such a body itself.  Parser applies it to the parse of a
 30	 * component (parseFileConvertExn) and to the import collector's view of a component
 31	 * that names a helper (importCollector), so that the repository knows the foreign
 32	 * api when it builds its graph, before every phase.
 33	 */
 34	public final class BuiltinPrimitiveRewriter {
 35	    private BuiltinPrimitiveRewriter() {}
 36	
 37	    public static final String HELPERS = "com.sun.fortress.nativeHelpers.";
 38	    private static volatile boolean on = false;
 39	    public static void setEnabled(boolean b) { on = b; }
 40	    public static boolean enabled() { return on; }
 41	
 42	    /** pkg -> (Class.method -> alias), in order of first use */
 43	    private static final class Aliases extends LinkedHashMap<String, LinkedHashMap<String, String>> {}
 44	
 45	    /** The component with each binding that names a static method rewritten; any other unit as it is. */
 46	    public static CompilationUnit rewrite(CompilationUnit cu) {
 47	        if (!enabled() || !(cu instanceof Component)) return cu;
 48	        Component c = (Component) cu;
 49	        Aliases aliases = new Aliases();
 50	        List<Decl> decls = new ArrayList<Decl>();
 51	        for (Decl d : c.getDecls()) decls.add(decl(d, false, aliases));
 52	        if (aliases.isEmpty()) return cu;
 53	        List<Import> imports = new ArrayList<Import>(c.getImports());
 54	        Span span = NodeUtil.getSpan(c);
 55	        for (Map.Entry<String, LinkedHashMap<String, String>> e : aliases.entrySet()) {
 56	            List<AliasedSimpleName> names = new ArrayList<AliasedSimpleName>();
 57	            for (Map.Entry<String, String> n : e.getValue().entrySet())
 58	                names.add(NodeFactory.makeAliasedSimpleName(span, NodeFactory.makeId(span, n.getKey()),
 59	                          Option.<IdOrOpOrAnonymousName>some(NodeFactory.makeId(span, n.getValue()))));
 60	            imports.add(NodeFactory.makeImportNames(span, Option.some("java"),
 61	                                                    NodeFactory.makeAPIName(span, e.getKey()), names));
 62	        }
 63	        return new Component(c.getInfo(), c.getName(), imports, decls, c.getComprises(), c.is_native(), c.getExports());
 64	    }
 65	
 66	    private static Decl decl(Decl d, boolean inType, Aliases aliases) {
 67	        if (d instanceof FnDecl) return fn((FnDecl) d, inType, aliases);
 68	        if (d instanceof TraitDecl) {
 69	            TraitDecl t = (TraitDecl) d;
 70	            return new TraitDecl(t.getInfo(), header(t.getHeader(), aliases), t.getSelfType(),
 71	                                 t.getExcludesClause(), t.getComprisesClause(), t.isComprisesEllipses());
 72	        }
 73	        if (d instanceof ObjectDecl) {
 74	            ObjectDecl o = (ObjectDecl) d;
 75	            return new ObjectDecl(o.getInfo(), header(o.getHeader(), aliases), o.getSelfType());
 76	        }
 77	        return d;
 78	    }
 79	
 80	    private static TraitTypeHeader header(TraitTypeHeader h, Aliases aliases) {
 81	        List<Decl> ds = new ArrayList<Decl>();
 82	        for (Decl d : h.getDecls()) ds.add(decl(d, true, aliases));
 83	        return new TraitTypeHeader(h.getStaticParams(), h.getMods(), h.getName(), h.getWhereClause(),
 84	                                   h.getThrowsClause(), h.getContract(), h.getExtendsClause(), h.getParams(), ds);
 85	    }
 86	
 87	    private static FnDecl fn(FnDecl f, boolean inType, Aliases aliases) {
 88	        if (f.getBody().isNone() || !(f.getBody().unwrap() instanceof Juxt)) return f;
 89	        Juxt body = (Juxt) f.getBody().unwrap();
 90	        List<Expr> es = body.getExprs();
 91	        if (!body.isTight() || es.size() != 2 || !(es.get(0) instanceof VarRef) || !(es.get(1) instanceof StringLiteralExpr))
 92	            return f;
 93	        if (!((VarRef) es.get(0)).getVarId().getText().equals("builtinPrimitive")) return f;
 94	        String s = ((StringLiteralExpr) es.get(1)).getText();
 95	        if (!s.startsWith(HELPERS)) return f;
 96	        int m = s.lastIndexOf('.'), k = s.lastIndexOf('.', m - 1);
 97	        if (!namesStaticMethod(s.substring(0, m), s.substring(m + 1)))
 98	            throw com.sun.fortress.exceptions.StaticError.make(
 99	                "builtinPrimitive names no static helper: " + s, es.get(1));
100	
101	        Span span = NodeUtil.getSpan(body);
102	        List<Expr> args = new ArrayList<Expr>();
103	        boolean hasSelf = false;
104	        for (Param p : NodeUtil.getParams(f)) {
105	            if (p.getVarargsType().isSome()) return f;
106	            if (p.getName().getText().equals("self")) hasSelf = true;
107	            else args.add(ExprFactory.makeVarRef(span, p.getName().getText()));
108	        }
109	        if (inType || hasSelf) args.add(0, ExprFactory.makeVarRef(span, "self"));
110	
111	        String pkg = s.substring(0, k), item = s.substring(k + 1);   // item = Class.method
112	        LinkedHashMap<String, String> inPkg = aliases.get(pkg);
113	        if (inPkg == null) aliases.put(pkg, inPkg = new LinkedHashMap<String, String>());
114	        String alias = inPkg.get(item);
115	        if (alias == null) inPkg.put(item, alias = "builtinPrimitive_" + item.replace('.', '_'));
116	
117	        Expr arg = args.isEmpty() ? ExprFactory.makeVoidLiteralExpr(span)
118	                 : args.size() == 1 ? ExprFactory.makeInParentheses(args.get(0))
119	                 : ExprFactory.makeTupleExpr(span, args);
120	        Expr call = ExprFactory.makeTightJuxt(body, Arrays.asList(ExprFactory.makeVarRef(span, alias), arg));
121	        return new FnDecl(f.getInfo(), f.getHeader(), f.getUnambiguousName(), Option.some(call),
122	                          f.getImplementsUnambiguousName());
123	    }
124	
125	    /** Does the file's text hold a builtinPrimitive string that names a helper? */
126	    public static boolean namesHelpers(java.io.File file) {
127	        try {
128	            return new String(java.nio.file.Files.readAllBytes(file.toPath()), "UTF-8").contains("\"" + HELPERS);
129	        } catch (java.io.IOException e) { return false; }
130	    }
131	
132	    private static boolean namesStaticMethod(String cls, String method) {
133	        try {
134	            for (Method x : Class.forName(cls, false, BuiltinPrimitiveRewriter.class.getClassLoader()).getMethods())
135	                if (x.getName().equals(method) && Modifier.isStatic(x.getModifiers())) return true;
136	        } catch (ClassNotFoundException e) { } catch (LinkageError e) { }
137	        return false;
138	    }
139	}

