273	    private MethodVisitor generateNewBody(int access, String desc, String signature,
274	            String[] exceptions, String name, String newName) {
275	
276	        Debug.debug(Debug.Type.COMPILER, 1, "generateNewBody: ", name,
277	                    " with desc ", desc);
278	
279	        SignatureParser sp = new SignatureParser(desc);
280	        
281	        List<String> desc_args = sp.getJVMArguments();
282	        String desc_result = sp.getJVMResult();
283	        List<String> fortress_args = new ArrayList<String>();
284	        List<fortressConverter> convert_args = new ArrayList<fortressConverter>();
285	
286	        String fsig = "(";
287	        StringBuilder buf = new StringBuilder();
288	        buf.append(fsig);
289	        for (String s : desc_args) {
290	             
291	            SignatureAndConverter s_a_c = toImplFFFF(s, name, false);
292	            buf.append(s_a_c.signature);
293	            fortress_args.add(s_a_c.signature);
294	            
295	            convert_args.add(s_a_c.converter);
296	        }
297	        fsig = buf.toString();
298	        SignatureAndConverter s_a_c = toImplFFFF(desc_result, name, true);
299	        fsig = fsig + ")" + s_a_c.signature;
300	        
301	        fortressConverter convert_result = s_a_c.converter;
302	    
303	        // FORWARDING METHOD, only with type conversions on the way in/out!
304	        MethodVisitor mv = cv.visitMethod(access, name, fsig, signature,
305	                exceptions);
306	        mv.visitCode();
307	        Label l0 = new Label();
308	        mv.visitLabel(l0);
309	        int count = 0;
310	        for (String s : fortress_args) {
311	            fortressConverter converter = convert_args.get(count);
312	            mv.visitVarInsn(Opcodes.ALOAD, count++);
313	            converter.convertArg(mv, s);
314	        }
315	
316	        Debug.debug(Debug.Type.COMPILER, 1, "className = ", inputClassName,
317	                    " name = ", name, " access = ", access);
318	
319	        mv.visitMethodInsn(Opcodes.INVOKESTATIC, inputClassName, name, sp
320	                .getSignature());
321	        
322	        convert_result.convertResult(mv, s_a_c.signature);
323	
324	        mv.visitInsn(Opcodes.ARETURN);
325	        mv.visitMaxs(2, 1);
326	        mv.visitEnd();
327	        return mv;
328	    }
