    public void forIntLiteralExpr(IntLiteralExpr x) {
        debug("forIntLiteral ", x);
        BigInteger bi = x.getIntVal();
        // bitLength() counts no sign bit, so l <= 31 is exactly the int range
        // and l <= 63 exactly the long range, for both signs.
        int l = bi.bitLength();
        if (l <= 31) {
            int y = bi.intValue();
